import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`google-ads-optimizer`,heroTitle:`Master your Google Ads in minutes`,heroSubtitle:`Perplexity Computer audits your campaigns, optimizes bids and copy, and delivers a performance playbook — automatically.`,hasInputUrl:!1,heroOverlaySteps:[`Analyzing your campaign structure, keywords, and bid strategies`,`Benchmarking ad copy and quality scores against top competitors`,`Identifying wasted spend, missed keywords, and conversion gaps`,`Optimized campaigns with budget recommendations — ready to launch`],generatingSteps:[`Reviewing your Google Ads account structure, keywords, and performance data`,`Designing an agent to audit quality scores, bid strategies, and ad copy effectiveness`,`Configuring competitor benchmarking and wasted spend analysis across campaigns`,`Setting up your optimization playbook with prioritized actions and budget reallocation`],featureSectionTitle:`From campaigns to optimized performance`,featureCardTitles:[`Connects to your ads stack`,`Outputs you can launch`],featureCardDescriptions:[`Computer breaks your project into tasks, spins up specialized agents, and matches each one to the AI model that does it best.`,`Google Analytics, Google Sheets, Google Search Console, Slack, Notion — Computer plugs into your tools so campaign data, reporting, and optimization live in one workflow.`,`Campaign audit scorecards. Keyword expansion lists. Ad copy rewrites with quality score projections. A budget reallocation plan with projected ROAS improvements.`],capabilitySectionTitle:`Your Google Ads team, on autopilot`,capabilitySectionSubtitle:`Describe your goals, step away, come back to fully optimized campaigns.`,capabilityCards:[{title:`Campaign Audits`,description:`Computer can analyze every campaign, ad group, and keyword — flagging low quality scores, poor-performing ads, and wasted spend across your entire account.`},{title:`Ad Copy Optimization`,description:`Computer can rewrite headlines, descriptions, and extensions — A/B testing variations against competitor messaging and search intent signals.`},{title:`Keyword Strategy`,description:`Computer can expand your keyword lists, add negative keywords to cut wasted spend, and surface high-intent terms your competitors are bidding on.`},{title:`Connect Your Tools`,description:`Computer can pull from Google Analytics, Google Search Console, Google Sheets, Notion, and more — build workflows across your entire advertising and reporting stack.`},{title:`Remember & Learn`,description:`Computer can remember your account structure, past optimizations, and performance trends across sessions — so every audit builds on prior results.`},{title:`Monitor & Alert`,description:`Computer can track campaign performance daily and flag when CPCs spike, quality scores drop, or competitors shift their bidding strategy.`}]});export{t as default};
